namespace py = pybind11;

namespace oc4::host
{
	namespace
	{
		std::wstring toWide(py::handle o)
		{
			PyObject* p = o.ptr();
			if (PyUnicode_Check(p))
			{
				std::wstring w(size_t(PyUnicode_GetSize(p)), L'\0');
				PyUnicode_AsWideChar(reinterpret_cast<PyUnicodeObject*>(p), w.data(), Py_ssize_t(w.size()));
				return w;
			}
			if (PyString_Check(p)) // game text is Latin-1 on the Python 2 side
			{
				std::wstring w;
				for (const char* s = PyString_AsString(p); *s; ++s)
					w.push_back(static_cast<unsigned char>(*s));
				return w;
			}
			return toWide(py::str(o));
		}

		py::object fromWide(const std::wstring& s)
		{
			return py::reinterpret_steal<py::object>(PyUnicode_FromWideChar(s.data(), Py_ssize_t(s.size())));
		}
	}

	void registerEngineClasses(Utility& utility)
	{
		auto cpe = py::reinterpret_borrow<py::module_>(PyImport_AddModule("CvPythonExtensions"));

		// Height fields for map scripts (FracVals are attached in oc4engine.py). The
		// generator argument is the DLL's CyRandom (CvRandom), e.g. gc.getGame().getMapRand().
		constexpr int xExp = CvFractal::DEFAULT_FRAC_X_EXP, yExp = CvFractal::DEFAULT_FRAC_Y_EXP;
		py::class_<CvFractal>(cpe, "CyFractal")
			.def(py::init<>())
			.def("fracInit",
				[](CvFractal& f, int w, int h, int grain, CvRandom& rand, int flags, int fracXExp, int fracYExp) {
					f.fracInit(w, h, grain, rand, flags, nullptr, fracXExp, fracYExp);
				},
				py::arg("w"), py::arg("h"), py::arg("grain"), py::arg("rand"), py::arg("flags"), py::arg("fracXExp") = xExp, py::arg("fracYExp") = yExp)
			.def("fracInitRifts",
				[](CvFractal& f, int w, int h, int grain, CvRandom& rand, int flags, CvFractal& rifts, int fracXExp, int fracYExp) {
					f.fracInit(w, h, grain, rand, flags, &rifts, fracXExp, fracYExp);
				},
				py::arg("w"), py::arg("h"), py::arg("grain"), py::arg("rand"), py::arg("flags"), py::arg("rifts"), py::arg("fracXExp") = xExp,
				py::arg("fracYExp") = yExp)
			.def("fracInitHints",
				[](CvFractal& f, int w, int h, int grain, CvRandom& rand, int flags, const std::vector<int>& hints, int fracXExp, int fracYExp) {
					std::vector<byte> bytes(hints.begin(), hints.end());
					f.fracInitHinted(w, h, grain, rand, bytes.data(), int(bytes.size()), flags, nullptr, fracXExp, fracYExp);
				},
				py::arg("w"), py::arg("h"), py::arg("grain"), py::arg("rand"), py::arg("flags"), py::arg("hints"), py::arg("fracXExp") = xExp,
				py::arg("fracYExp") = yExp)
			.def("getHeight", &CvFractal::getHeight)
			.def("getHeightFromPercent", &CvFractal::getHeightFromPercent);

		// Host services for oc4engine.py.
		auto host = py::reinterpret_borrow<py::module_>(PyImport_AddModule("oc4host"));
		host.def("get_text", [&utility](py::handle key, py::iterable args) {
			std::vector<TextManager::Arg> values;
			for (py::handle a : args)
			{
				if (PyInt_Check(a.ptr()) || PyLong_Check(a.ptr()) || PyBool_Check(a.ptr()))
					values.emplace_back(static_cast<long long>(PyLong_AsLongLong(a.ptr())));
				else if (PyFloat_Check(a.ptr()))
					values.emplace_back(PyFloat_AsDouble(a.ptr()));
				else
					values.emplace_back(toWide(a));
			}
			return fromWide(utility.text().get(toWide(key), values));
		});
		host.def("get_object_text", [&utility](py::handle key, int form) {
			return fromWide(std::wstring(utility.getObjectText(CvWString(toWide(key)), static_cast<uint>(form), false)));
		});
		host.def("unimplemented", [](const std::string& what) { unimplemented(what.c_str()); });
		host.def("log", [&utility](const std::string& file, py::handle text) {
			if (PyUnicode_Check(text.ptr()))
			{
				py::object bytes = py::reinterpret_steal<py::object>(PyUnicode_AsUTF8String(text.ptr()));
				if (bytes)
					utility.logRaw(file, PyString_AsString(bytes.ptr()));
				else
					PyErr_Clear();
			}
			else if (PyString_Check(text.ptr()))
				utility.logRaw(file, std::string_view(PyString_AsString(text.ptr()), size_t(PyString_Size(text.ptr()))));
		});

		// The Python half: module oc4engine adds its classes to CvPythonExtensions, oc4screens
		// the screens (CyGInterfaceScreen, CyInterface) over them, oc4menu the main menu, oc4turnlog the turn log,
		// oc4options the options screen's tab control and the player's profile (CyGTabCtrl, CyUserProfile).
		registerScreenFunctions(utility);
		for (const auto& [source, name] : { std::pair{ kOc4EnginePy, "oc4engine" }, std::pair{ kOc4ScreensPy, "oc4screens" }, std::pair{ kOc4MenuPy, "oc4menu" }, std::pair{ kOc4TurnLogPy, "oc4turnlog" },
				 std::pair{ kOc4OptionsPy, "oc4options" }, std::pair{ kOc4WbPy, "oc4wb" } })
		{
			const std::string file = std::string(name) + ".py";
			PyObject* code = Py_CompileString(reinterpret_cast<const char*>(source), file.c_str(), Py_file_input);
			PyObject* module = code ? PyImport_ExecCodeModuleEx(const_cast<char*>(name), code, const_cast<char*>(file.c_str())) : nullptr;
			Py_XDECREF(code);
			if (!module)
			{
				PyErr_Print();
				throw std::runtime_error(file + " failed");
			}
			Py_DECREF(module);
		}
#ifndef _WIN32
		// Off Windows: _winreg for mods' scripts that ask the registry where My Documents is (BUG).
		{
			PyObject* code = Py_CompileString(reinterpret_cast<const char*>(kOc4WinregPy), "oc4winreg.py", Py_file_input);
			PyObject* module = code ? PyImport_ExecCodeModuleEx(const_cast<char*>("_winreg"), code, const_cast<char*>("oc4winreg.py")) : nullptr;
			Py_XDECREF(code);
			if (!module)
			{
				PyErr_Print();
				throw std::runtime_error("oc4winreg.py failed");
			}
			Py_DECREF(module);
		}
#else
		(void)kOc4WinregPy;
#endif
	}
}
